<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { Plus, Save, X } from 'lucide-vue-next'
import DeliveryLocationPicker from '../components/DeliveryLocationPicker.vue'
import { loadAdminCatalog, saveCategory, saveProduct, saveRestaurant } from '../services/adminCatalogService'
const props = defineProps({ module: { type: String, required: true } }); const catalog = reactive({ restaurants: [], categories: [], products: [], zones: [] }); const loading = ref(true); const error = ref(''); const editing = ref(null); const locationPickerOpen = ref(false)
const restaurantForm = reactive({ zona_id: '', nombre: '', tipo_comida: 'Otros', descripcion: '', imagen_url: '', banner_url: '', calificacion: 0, cantidad_resenas: 0, tiempo_preparacion_min: 30, pos_x: null, pos_y: null, activo: true }); const categoryForm = reactive({ restaurante_id: '', nombre: '', orden: 0, activa: true }); const productForm = reactive({ restaurante_id: '', categoria_id: '', nombre: '', descripcion: '', precio: 0, imagen_url: '', disponible: true }); const selectedCategories = computed(() => catalog.categories.filter((item) => item.restaurante_id === productForm.restaurante_id)); const title = computed(() => ({ restaurants: 'Restaurantes', categories: 'Categorías', products: 'Productos' }[props.module])); const rows = computed(() => props.module === 'restaurants' ? catalog.restaurants : props.module === 'categories' ? catalog.categories : catalog.products)
async function load() { try { Object.assign(catalog, await loadAdminCatalog()) } catch (e) { error.value = e.message } finally { loading.value = false } }
function reset() { editing.value = {}; Object.assign(restaurantForm, { zona_id: catalog.zones[0]?.id || '', nombre: '', tipo_comida: 'Otros', descripcion: '', imagen_url: '', banner_url: '', calificacion: 0, cantidad_resenas: 0, tiempo_preparacion_min: 30, pos_x: null, pos_y: null, activo: true }); Object.assign(categoryForm, { restaurante_id: catalog.restaurants[0]?.id || '', nombre: '', orden: 0, activa: true }); Object.assign(productForm, { restaurante_id: catalog.restaurants[0]?.id || '', categoria_id: '', nombre: '', descripcion: '', precio: 0, imagen_url: '', disponible: true }) }
function edit(item) { editing.value = item; if (props.module === 'restaurants') Object.assign(restaurantForm, item); else if (props.module === 'categories') Object.assign(categoryForm, item); else Object.assign(productForm, item) }
function closeForm() { editing.value = null; locationPickerOpen.value = false }
function confirmLocation(point) { restaurantForm.pos_x = point.longitud; restaurantForm.pos_y = point.latitud; locationPickerOpen.value = false }
async function submit() { try { if (props.module === 'restaurants') await saveRestaurant(restaurantForm, editing.value?.id); else if (props.module === 'categories') await saveCategory(categoryForm, editing.value?.id); else await saveProduct(productForm, editing.value?.id); await load(); closeForm() } catch (e) { error.value = e.message } }
onMounted(load)
</script>
<template><section class="admin-view"><div class="admin-view-heading"><div><span class="admin-eyebrow">CATÁLOGO</span><h2>{{ title }}</h2><p>Administra el catálogo de la aplicación.</p></div><button class="admin-primary-button" @click="reset"><Plus :size="17" /> Agregar {{ module === 'restaurants' ? 'restaurante' : module === 'categories' ? 'categoría' : 'producto' }}</button></div><p v-if="error" class="admin-alert">{{ error }}</p><div v-if="loading" class="admin-empty">Cargando catálogo…</div><template v-else><div v-if="editing" class="admin-panel admin-form-panel"><div class="admin-panel-heading"><h3>{{ editing.id ? 'Editar' : 'Nuevo' }} {{ module === 'restaurants' ? 'restaurante' : module === 'categories' ? 'categoría' : 'producto' }}</h3><button class="admin-icon-button" @click="closeForm"><X :size="18" /></button></div><form class="admin-form-grid" @submit.prevent="submit"><template v-if="module === 'restaurants'"><label>Nombre<input v-model="restaurantForm.nombre" required /></label><label>Zona<select v-model="restaurantForm.zona_id" required><option v-for="z in catalog.zones" :key="z.id" :value="z.id">{{ z.nombre }}</option></select></label><label>Tipo de comida<input v-model="restaurantForm.tipo_comida" /></label><label>Tiempo estimado<input v-model.number="restaurantForm.tiempo_preparacion_min" type="number" min="1" /></label><label>Calificación<input v-model.number="restaurantForm.calificacion" type="number" min="0" max="5" step="0.1" /></label><label>Cantidad de reseñas<input v-model.number="restaurantForm.cantidad_resenas" type="number" min="0" /></label><label>Logotipo<input v-model="restaurantForm.imagen_url" type="url" /></label><label>Portada<input v-model="restaurantForm.banner_url" type="url" /></label><label class="full">Descripción<textarea v-model="restaurantForm.descripcion" rows="2" /></label><div class="full admin-location-field"><strong>Ubicación del restaurante</strong><small>{{ restaurantForm.pos_y && restaurantForm.pos_x ? `Coordenadas: ${Number(restaurantForm.pos_y).toFixed(6)}, ${Number(restaurantForm.pos_x).toFixed(6)}` : 'Selecciona la ubicación en el mapa.' }}</small><button type="button" class="location-select-button" @click="locationPickerOpen = true">Seleccionar ubicación en el mapa</button></div><label class="check"><input v-model="restaurantForm.activo" type="checkbox" /> Activo</label></template><template v-else-if="module === 'categories'"><label>Restaurante<select v-model="categoryForm.restaurante_id" required><option v-for="r in catalog.restaurants" :key="r.id" :value="r.id">{{ r.nombre }}</option></select></label><label>Nombre<input v-model="categoryForm.nombre" required /></label><label>Orden<input v-model.number="categoryForm.orden" type="number" min="0" /></label><label class="check"><input v-model="categoryForm.activa" type="checkbox" /> Activa</label></template><template v-else><label>Restaurante<select v-model="productForm.restaurante_id" required><option v-for="r in catalog.restaurants" :key="r.id" :value="r.id">{{ r.nombre }}</option></select></label><label>Categoría<select v-model="productForm.categoria_id" required><option v-for="c in selectedCategories" :key="c.id" :value="c.id">{{ c.nombre }}</option></select></label><label>Nombre<input v-model="productForm.nombre" required /></label><label>Precio<input v-model.number="productForm.precio" type="number" min="0" step="0.01" required /></label><label class="full">Descripción<textarea v-model="productForm.descripcion" rows="2" /></label><label class="full">Fotografía<input v-model="productForm.imagen_url" type="url" /></label><label class="check"><input v-model="productForm.disponible" type="checkbox" /> Disponible</label></template><button class="admin-primary-button full" type="submit"><Save :size="17" /> Guardar cambios</button></form></div><DeliveryLocationPicker v-if="locationPickerOpen" :latitud="restaurantForm.pos_y" :longitud="restaurantForm.pos_x" @cancel="locationPickerOpen = false" @confirm="confirmLocation" /><div class="admin-panel admin-table-wrap"><table class="admin-table"><thead><tr><th v-if="module === 'restaurants'">Logotipo</th><th>Nombre</th><th v-if="module !== 'restaurants'">Restaurante</th><th v-if="module === 'products'">Categoría</th><th v-if="module === 'restaurants'">Tipo · Calificación · Reseñas</th><th v-if="module === 'products'">Precio</th><th>Estado</th><th /></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td v-if="module === 'restaurants'"><img class="admin-thumb" :src="item.imagen_url || '/logos/logo.png'" :alt="item.nombre" /></td><td><strong>{{ item.nombre }}</strong><small v-if="module === 'restaurants'">{{ item.zonas?.nombre || 'Sin zona' }} · {{ item.pos_y && item.pos_x ? 'Ubicación configurada' : 'Sin ubicación' }}</small></td><td v-if="module !== 'restaurants'">{{ item.restaurantes?.nombre || catalog.restaurants.find((r) => r.id === item.restaurante_id)?.nombre || '—' }}</td><td v-if="module === 'products'">{{ item.categorias?.nombre || catalog.categories.find((c) => c.id === item.categoria_id)?.nombre || '—' }}</td><td v-if="module === 'restaurants'">{{ item.tipo_comida }} · ★ {{ item.calificacion || 0 }} · {{ item.cantidad_resenas || 0 }} reseñas</td><td v-if="module === 'products'">${{ Number(item.precio).toFixed(2) }}</td><td><span class="admin-status-pill">{{ item.activo === false || item.activa === false || item.disponible === false ? 'Inactivo' : 'Activo' }}</span></td><td><button class="admin-link-button" @click="edit(item)">Editar</button></td></tr></tbody></table><div v-if="!rows.length" class="admin-empty">No hay registros.</div></div></template></section></template>
